css:
.tc-calc{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:clamp(24px,4vw,48px);align-items:start;text-align:left}
.tc-calc__form{background:#fff;color:#14151A;padding:clamp(20px,4vw,40px);display:grid;gap:20px;margin:0}
.tc-calc__field{display:flex;flex-direction:column;gap:6px}
.tc-calc__label{font-weight:600;font-size:15px;line-height:1.6}
.tc-calc__wrap{position:relative}
.tc-calc__input{font:400 16px Inter,sans-serif;padding:12px 14px;min-height:48px;box-sizing:border-box;width:100%;border:1px solid #54565C;border-radius:0;background:#fff;color:#14151A}
.tc-calc__input:focus-visible{outline:3px solid #C41230;outline-offset:2px}
.tc-calc__pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;align-items:end}
.tc-calc__req{margin:0;font-size:14px;color:#54565C;line-height:1.6}
.tc-calc__out{background:#0E0F13;color:#fff;padding:clamp(20px,4vw,40px)}
.tc-calc__dl{margin:0}
.tc-calc__row{padding:16px 0;border-bottom:1px solid #6B6D74}
.tc-calc__dt{font:600 14px Oswald,sans-serif;letter-spacing:.1em;text-transform:uppercase}
.tc-calc__dd{margin:4px 0 0;font:700 24px/1.1 Oswald,sans-serif}
.tc-calc__dd--big{font-size:clamp(36px,5vw,52px)}
